const assistantShell = {
  marginTop: 8,
  padding: "14px 16px",
  borderRadius: 10,
  border: "1px solid #e2e8f0",
  background: "linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%)",
  borderLeft: "4px solid #6366f1",
};

const codeShell = {
  position: "relative",
  margin: "12px 0",
  borderRadius: 8,
  border: "1px solid #334155",
  background: "#0f172a",
  overflow: "hidden",
};

const codePre = {
  margin: 0,
  padding: "12px 14px 14px",
  overflowX: "auto",
  fontSize: 13,
  lineHeight: 1.5,
  fontFamily: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace",
  color: "#e2e8f0",
};

function splitIntoSegments(raw) {
  const segments = [];
  let cursor = 0;
  const src = raw || "";
  while (cursor < src.length) {
    const open = src.indexOf("```", cursor);
    if (open === -1) {
      if (cursor < src.length) segments.push({ type: "text", content: src.slice(cursor) });
      break;
    }
    if (open > cursor) segments.push({ type: "text", content: src.slice(cursor, open) });
    const afterTicks = open + 3;
    const lineEnd = src.indexOf("\n", afterTicks);
    let codeStart;
    let lang = "";
    if (lineEnd === -1) {
      codeStart = afterTicks;
    } else {
      const maybeLang = src.slice(afterTicks, lineEnd).trim();
      if (maybeLang && /^[\w#+.:-]+$/.test(maybeLang)) {
        lang = maybeLang;
        codeStart = lineEnd + 1;
      } else {
        codeStart = afterTicks;
      }
    }
    const close = src.indexOf("```", codeStart);
    if (close === -1) {
      segments.push({ type: "text", content: src.slice(open) });
      break;
    }
    const code = src.slice(codeStart, close).replace(/\n$/, "");
    segments.push({ type: "code", lang, code });
    cursor = close + 3;
  }
  return segments;
}

function renderInline(text, isDark) {
  const parts = String(text).split(/(\*\*[^*]+\*\*)/g);
  return parts.map((part, idx) => {
    if (part.startsWith("**") && part.endsWith("**") && part.length > 4) {
      const inner = part.slice(2, -2);
      return (
        <strong key={idx} style={{ fontWeight: 700, color: isDark ? "#f1f5f9" : "#312e81" }}>
          {inner}
        </strong>
      );
    }
    return <span key={idx}>{part}</span>;
  });
}

function renderTextBlock(content, baseKey, isDark) {
  const lines = content.replace(/\r\n/g, "\n").split("\n");
  const elements = [];
  let paraBuf = [];
  let key = 0;

  const flushPara = () => {
    if (paraBuf.length === 0) return;
    const paraText = paraBuf.join("\n").trim();
    paraBuf = [];
    if (!paraText) return;
    elements.push(
      <p key={`${baseKey}-p-${key++}`} style={{ margin: "0 0 10px", lineHeight: 1.55, color: isDark ? "#e2e8f0" : "#334155" }}>
        {renderInline(paraText, isDark)}
      </p>
    );
  };

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    const trimmed = line.trim();
    if (!trimmed) {
      flushPara();
      i += 1;
      continue;
    }

    if (/^#{1,3}\s+/.test(trimmed)) {
      flushPara();
      const level = trimmed.match(/^#+/)[0].length;
      const text = trimmed.replace(/^#+\s+/, "");
      const HeadingTag = level === 1 ? "h3" : level === 2 ? "h4" : "h5";
      const size = level === 1 ? "1.15rem" : level === 2 ? "1.05rem" : "1rem";
      elements.push(
        <HeadingTag
          key={`${baseKey}-h-${key++}`}
          style={{
            margin: "14px 0 8px",
            fontWeight: 700,
            color: isDark ? "#f1f5f9" : "#1e293b",
            fontSize: size,
            lineHeight: 1.35,
          }}
        >
          {renderInline(text, isDark)}
        </HeadingTag>
      );
      i += 1;
      continue;
    }

    if (/^\*\*(.+)\*\*$/.test(trimmed)) {
      flushPara();
      const inner = trimmed.slice(2, -2);
      elements.push(
        <h4
          key={`${baseKey}-boldline-${key++}`}
          style={{
            margin: "12px 0 6px",
            fontWeight: 700,
            fontSize: "1.02rem",
            color: isDark ? "#f1f5f9" : "#1e293b",
            lineHeight: 1.35,
          }}
        >
          {inner}
        </h4>
      );
      i += 1;
      continue;
    }

    if (/^[-*•]\s+/.test(trimmed)) {
      flushPara();
      const items = [];
      while (i < lines.length && /^[-*•]\s+/.test(lines[i].trim())) {
        items.push(lines[i].trim().replace(/^[-*•]\s+/, ""));
        i += 1;
      }
      elements.push(
        <ul
          key={`${baseKey}-ul-${key++}`}
          style={{
            margin: "6px 0 12px",
            paddingLeft: 22,
            color: isDark ? "#cbd5e1" : "#334155",
            lineHeight: 1.55,
          }}
        >
          {items.map((it, j) => (
            <li key={j} style={{ marginBottom: 6 }}>
              {renderInline(it, isDark)}
            </li>
          ))}
        </ul>
      );
      continue;
    }

    if (/^\d+\.\s+/.test(trimmed)) {
      flushPara();
      const items = [];
      while (i < lines.length && /^\d+\.\s+/.test(lines[i].trim())) {
        items.push(lines[i].trim().replace(/^\d+\.\s+/, ""));
        i += 1;
      }
      elements.push(
        <ol
          key={`${baseKey}-ol-${key++}`}
          style={{
            margin: "6px 0 12px",
            paddingLeft: 22,
            color: isDark ? "#cbd5e1" : "#334155",
            lineHeight: 1.55,
          }}
        >
          {items.map((it, j) => (
            <li key={j} style={{ marginBottom: 6 }}>
              {renderInline(it, isDark)}
            </li>
          ))}
        </ol>
      );
      continue;
    }

    paraBuf.push(line);
    i += 1;
  }
  flushPara();
  return elements;
}

function CodeBlock({ lang, code, isDark }) {
  const [copied, setCopied] = useState(false);

  const copy = useCallback(() => {
    navigator.clipboard.writeText(code).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }, [code]);

  const codeShell = {
    position: "relative",
    margin: "12px 0",
    borderRadius: 8,
    border: `1px solid ${isDark ? '#334155' : '#d1d5db'}`,
    background: isDark ? '#0f172a' : '#f8fafc',
    overflow: "hidden",
  };

  const codePre = {
    margin: 0,
    padding: "12px 14px 14px",
    overflowX: "auto",
    fontSize: 13,
    lineHeight: 1.5,
    fontFamily: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace",
    color: isDark ? '#e2e8f0' : '#1f2937',
  };

  return (
    <div style={codeShell}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 8,
          padding: "6px 10px",
          background: isDark ? '#1e293b' : '#e5e7eb',
          borderBottom: `1px solid ${isDark ? '#334155' : '#d1d5db'}`,
        }}
      >
        <span style={{ fontSize: 11, color: isDark ? '#94a3b8' : '#6b7280', textTransform: "uppercase", letterSpacing: "0.04em" }}>
          {lang || "code"}
        </span>
        <button
          type="button"
          onClick={copy}
          style={{
            cursor: "pointer",
            fontSize: 12,
            padding: "4px 10px",
            borderRadius: 6,
            border: `1px solid ${isDark ? '#475569' : '#9ca3af'}`,
            background: copied ? (isDark ? '#22c55e' : '#16a34a') : (isDark ? '#334155' : '#d1d5db'),
            color: copied ? '#ffffff' : (isDark ? '#f8fafc' : '#374151'),
            transition: 'all 0.2s'
          }}
        >
          {copied ? "Copied!" : "Copy"}
        </button>
      </div>
      <pre style={codePre}>
        <code>{code}</code>
      </pre>
    </div>
  );
}

function AssistantOutput({ text, isDark }) {
  const segments = splitIntoSegments(text);
  const assistantShell = {
    marginTop: 8,
    padding: "14px 16px",
    borderRadius: 10,
    border: `1px solid ${isDark ? '#334155' : '#e2e8f0'}`,
    background: isDark ? "linear-gradient(180deg, #1e293b 0%, #0f172a 100%)" : "linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%)",
    borderLeft: `4px solid ${isDark ? '#6366f1' : '#6366f1'}`,
  };

  return (
    <div style={assistantShell} aria-label="Gemini reply">
      {segments.map((seg, idx) => {
        if (seg.type === "code") {
          return <CodeBlock key={`c-${idx}`} lang={seg.lang} code={seg.code} isDark={isDark} />;
        }
        return <div key={`t-${idx}`}>{renderTextBlock(seg.content, `seg-${idx}`, isDark)}</div>;
      })}
    </div>
  );
}

export default function Gemini() {
  const { theme } = useTheme();
  const isDark = theme === "dark";
  const messagesEndRef = useRef(null);
  const [prompt, setPrompt] = useState("");
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [apiKey, setApiKey] = useState("");
  const [models, setModels] = useState([]);
  const [selectedModel, setSelectedModel] = useState(GEMINI_MODEL);
 const containerRef = useRef(null);
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const fetchModels = async () => {
    if (!apiKey) return;
    setError("");
    try {
      const res = await axios.get(
        `https://generativelanguage.googleapis.com/v1beta/models?key=${apiKey}`
      );
      const modelList = res.data?.models || [];
      const filtered = modelList
        .map((m) => m.name.replace("models/", ""))
        .filter((name) => name.includes("gemini"));
      setModels(filtered);
      if (filtered.length > 0) setSelectedModel(filtered[0]);
      else setSelectedModel("");
    } catch (err) {
      setError("Model fetch error: " + (err?.response?.data?.error?.message || err.message));
      setModels([]);
      setSelectedModel("");
    }
  };

   const toggleFullScreen = () => {
    const el = containerRef.current
    if (!el) return
    if (!document.fullscreenElement) {
      if (el.requestFullscreen) el.requestFullscreen()
    } else {
      if (document.exitFullscreen) document.exitFullscreen()
    }
  }

  const askGemini = async () => {
    const userText = prompt.trim();
    if (!userText || loading) return;
    setError("");
    setLoading(true);
    setPrompt("");
    setMessages((prev) => [...prev, { role: "user", text: userText }]);
    try {
      const res = await axios.post(
        "/api/gemini", // Use your backend endpoint here
        {
          prompt: userText,
          model: selectedModel,
          apiKey: apiKey,
        },
        { headers: { "Content-Type": "application/json" } }
      );
      const botText =
        res.data?.reply || res.data?.result || res.data?.bot || "No response from backend.";
      setMessages((prev) => [...prev, { role: "assistant", text: botText }]);
    } catch (err) {
      const msg = err?.response?.data?.error || err?.message || "Something went wrong.";
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  const onSubmit = (e) => {
    e.preventDefault();
    askGemini();
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      askGemini();
    }
  };

  // Layout styles
  const bg = isDark ? "#0b1220" : "#f7fafc";
  const cardBg = isDark ? "#181f2e" : "#fff";
  const textColor = isDark ? "#e6eef8" : "#0f1724";
  const borderColor = isDark ? "#232b3d" : "#e5e7eb";
  const accentColor = "#6366f1";
  const inputBg = isDark ? "#232b3d" : "#f3f4f6";

  return (
<div
ref={containerRef} 
  style={{
    width: "100%",
    height: "100vh", // ✅ full screen base
    background: bg,
    color: textColor,
    display: "flex",
    flexDirection: "column",
    overflow: "hidden", // ✅ prevent scroll bugs
  }}
>
      {/* Header & Controls */}
     <header
      style={{
        background: cardBg,
        borderBottom: `1px solid ${borderColor}`,
        padding: "14px 20px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: 12,
        width: "100%",
        flexShrink: 0,
        position: "sticky",
        top: 0,
        zIndex: 5,
        backdropFilter: "blur(10px)", // 🔥 modern AI look
      }}
    >
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <span
            style={{
              fontSize: "2.1rem",
              marginRight: 8,
              display: "flex",
              alignItems: "center",
            }}
            role="img"
            aria-label="Gemini"
          >
            🤖
          </span>
          <span
            style={{
              fontWeight: 700,
              fontSize: "1.35rem",
              letterSpacing: "-1px",
              color: accentColor,
            }}
          >
            Gemini AI Chat
          </span>
        </div>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
            flexWrap: "wrap",
          }}
        >
          <input
            type="password"
            placeholder="API Key"
            value={apiKey}
            onChange={(e) => setApiKey(e.target.value)}
            style={{
              padding: "7px 12px",
              borderRadius: 7,
              border: `1px solid ${borderColor}`,
              background: inputBg,
              color: textColor,
              fontSize: "1rem",
              minWidth: 120,
              width: 170,
              outline: "none",
              transition: "border 0.2s",
            }}
          />
          <button
            onClick={fetchModels}
            disabled={!apiKey}
            style={{
              padding: "7px 16px",
              borderRadius: 7,
              border: "none",
              background: apiKey ? accentColor : "#a5b4fc",
              color: "#fff",
              fontWeight: 600,
              fontSize: "1rem",
              cursor: apiKey ? "pointer" : "not-allowed",
              transition: "background 0.2s",
              display: "flex",
              alignItems: "center",
              gap: 6,
            }}
            title="Load Models"
          >
            <i className="bi bi-cloud-download" style={{ fontSize: "1.1rem" }} />
            Load
          </button>
          <button
          onClick={toggleFullScreen}
            style={{
              padding: "7px 12px",
              borderRadius: 7,
              border: `1px solid ${borderColor}`,
              background: "transparent",
              color: textColor,
              cursor: "pointer",
            }}
            title="Toggle Fullscreen"
          >
            <i className="bi bi-arrows-fullscreen"></i>
          </button>
          {models.length > 0 && (
            <select
              value={selectedModel}
              onChange={(e) => setSelectedModel(e.target.value)}
              style={{
                padding: "7px 10px",
                borderRadius: 7,
                border: `1px solid ${borderColor}`,
                background: inputBg,
                color: textColor,
                fontSize: "0.98rem",
                minWidth: 90,
                width: 140,
                outline: "none",
                fontWeight: 500,
                height: 36,
              }}
              title="Select Model"
            >
              {models.map((m, i) => (
                <option key={i} value={m}>
                  {m}
                </option>
              ))}
            </select>
          )}
          <button
            onClick={() => {
              setMessages([]);
              setPrompt("");
              setError("");
            }}
            title="Clear chat"
            style={{
              padding: "7px 12px",
              borderRadius: 7,
              border: `1px solid ${borderColor}`,
              background: "transparent",
              color: accentColor,
              fontSize: "1.15rem",
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              gap: 0,
            }}
          >
            <i className="bi bi-trash3" />
          </button>
        </div>
      </header>

      {/* Error Banner */}
      {error && (
        <div
          style={{
            padding: "12px 20px",
            borderRadius: 10,
            background: isDark ? "#dc26261a" : "#fef2f2",
            border: `1px solid ${isDark ? "#dc26263d" : "#fecaca"}`,
            color: isDark ? "#fca5a5" : "#dc2626",
            fontWeight: 500,
            margin: "12px auto 0 auto",
            maxWidth: 600,
            width: "100%",
            textAlign: "center",
          }}
        >
          <i className="bi bi-exclamation-triangle me-2"></i>
          {error}
        </div>
      )}

      {/* Chat Container */}
     <main
        style={{
          flex: 1,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          overflowY: "auto",
          padding: "20px 10px 100px", // space for input
        }}
      >
      <div
        style={{
          width: "100%",
          maxWidth: 900, // 🔥 better for AI
          display: "flex",
          flexDirection: "column",
          gap: 12,
        }}
      >
          {messages.length === 0 ? (
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                flex: 1,
                color: isDark ? "#64748b" : "#9ca3af",
                textAlign: "center",
                minHeight: 200,
              }}
            >
              <i
                className="bi bi-chat-dots"
                style={{ fontSize: "3rem", marginBottom: 16, opacity: 0.5 }}
              ></i>
              <h4 style={{ margin: 0, fontWeight: 500 }}>Start a conversation</h4>
              <p style={{ margin: "8px 0 0 0", fontSize: "0.95rem" }}>
                Enter your API key, load models, select a model, and chat!
              </p>
            </div>
          ) : (
            <>
              {messages.map((msg, index) => (
                <div
                  key={index}
                  style={{
                    display: "flex",
                    justifyContent: msg.role === "user" ? "flex-end" : "flex-start",
                    marginBottom: 10,
                  }}
                >
                  <div
                   style={{
                    maxWidth: "75%",
                    padding: "14px 16px",
                    borderRadius: msg.role === "user"
                      ? "16px 16px 4px 16px"
                      : "16px 16px 16px 4px",

                    background:
                      msg.role === "user"
                        ? `linear-gradient(135deg, ${accentColor}, #6366f1)`
                        : isDark
                        ? "rgba(30,41,59,0.8)"
                        : "#f8fafc",

                    backdropFilter: "blur(6px)",
                    border:
                      msg.role === "assistant"
                        ? `1px solid ${borderColor}`
                        : "none",

                    boxShadow:
                      msg.role === "user"
                        ? "0 6px 18px rgba(99,102,241,0.25)"
                        : "0 2px 8px rgba(0,0,0,0.05)",
                   }}
                  >
                    <div
                      style={{
                        fontSize: "0.8rem",
                        opacity: 0.7,
                        marginBottom: 6,
                        fontWeight: 500,
                        letterSpacing: "0.01em",
                        textAlign: msg.role === "user" ? "right" : "left",
                      }}
                    >
                      {msg.role === "user" ? (
                        <span>
                          <i className="bi bi-person-circle" style={{ marginRight: 4 }} />
                          You
                        </span>
                      ) : (
                        <span>
                          <i className="bi bi-stars" style={{ marginRight: 4 }} />
                          Gemini
                        </span>
                      )}
                    </div>
                    {msg.role === "user" ? (
                      <div style={{ lineHeight: 1.6, whiteSpace: "pre-wrap" }}>
                        {msg.text}
                      </div>
                    ) : (
                      <AssistantOutput text={msg.text} isDark={isDark} />
                    )}
                  </div>
                </div>
              ))}
              {loading && (
                <div
                  style={{
                    display: "flex",
                    justifyContent: "flex-start",
                    marginBottom: 16,
                  }}
                >
                  <div
                    style={{
                      padding: "12px 16px",
                      borderRadius: 16,
                      background: isDark ? "#232b3d" : "#f3f4f6",
                      border: `1px solid ${borderColor}`,
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                    }}
                  >
                    <div className="spinner-border spinner-border-sm" role="status"></div>
                    <span
                      style={{
                        fontSize: "0.95rem",
                        color: isDark ? "#cbd5e1" : "#6b7280",
                      }}
                    >
                      Gemini is thinking...
                    </span>
                  </div>
                </div>
              )}
            </>
          )}
          <div ref={messagesEndRef} />
        </div>
      </main>

      {/* Input Area */}
        <form
          onSubmit={onSubmit}
          style={{
            background: cardBg,
            borderTop: `1px solid ${borderColor}`,
            padding: "14px 18px",
            display: "flex",
            gap: 10,
            width: "100%",
            position: "sticky", // 🔥 FIXED overlapping issue
            bottom: 0,
            zIndex: 5,
          }}
        >
        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={
            selectedModel
              ? "Type your message here... (Ctrl+Enter to send)"
              : "Please load and select a model first..."
          }
          rows={2}
          disabled={loading || !selectedModel}
         style={{
            flex: 1,
            padding: "12px 14px",
            borderRadius: 12,
            border: `1px solid ${borderColor}`,
            background: inputBg,
            color: textColor,
            fontSize: "1rem",
            resize: "none",
            outline: "none",
            minHeight: 44,
            maxHeight: 140,
            transition: "all 0.2s",
          }}
        />
        <button
          type="submit"
          disabled={loading || !prompt.trim() || !selectedModel}
         style={{
              padding: "12px 18px",
              borderRadius: 12,
              border: "none",
              background:
                !loading && prompt.trim() && selectedModel
                  ? `linear-gradient(135deg, ${accentColor}, #6366f1)`
                  : "#94a3b8",
              color: "#fff",
              fontWeight: 600,
              cursor:
                !loading && prompt.trim() && selectedModel
                  ? "pointer"
                  : "not-allowed",
              transition: "all 0.2s",
            }}
        > 
          {loading ? (
            <>
              <div className="spinner-border spinner-border-sm" role="status"></div>
              Sending
            </>
          ) : (
            <>
              <i className="bi bi-send" />
              Send
            </>
          )}
        </button>
      </form>
    </div>
  );
}
